import{_ as d,o as e,c as a,a2 as s}from"./chunks/framework.Cd7uensT.js";const b=JSON.parse('{"title":"观测与审计辅助接口","description":"","frontmatter":{},"headers":[],"relativePath":"api/system-observability.md","filePath":"api/system-observability.md","lastUpdated":1794561975000}'),i={name:"api/system-observability.md"};function o(r,t,h,n,l,c){return e(),a("div",null,[...t[0]||(t[0]=[s('<h1 id="观测与审计辅助接口" tabindex="-1">观测与审计辅助接口 <a class="header-anchor" href="#观测与审计辅助接口" aria-label="Permalink to &quot;观测与审计辅助接口&quot;">​</a></h1><p>本页涵盖三类与系统可观测性、审计安全相关的接口：前端错误上报、危险操作审计、公开设备信息牌。</p><hr><h2 id="前端错误日志上报" tabindex="-1">前端错误日志上报 <a class="header-anchor" href="#前端错误日志上报" aria-label="Permalink to &quot;前端错误日志上报&quot;">​</a></h2><h3 id="接口说明" tabindex="-1">接口说明 <a class="header-anchor" href="#接口说明" aria-label="Permalink to &quot;接口说明&quot;">​</a></h3><div class="language-http vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">http</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">POST</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> /api/frontend-logs</span></span></code></pre></div><p><strong>免鉴权</strong>（位于公开端点白名单）：前端在未登录、Token 失效或登录页崩溃时同样需要上报错误。</p><h3 id="触发来源" tabindex="-1">触发来源 <a class="header-anchor" href="#触发来源" aria-label="Permalink to &quot;触发来源&quot;">​</a></h3><p>前端 <code>frontendLogger</code> 全局捕获以下三类异常并统一上报后端：</p><table tabindex="0"><thead><tr><th>来源</th><th>说明</th></tr></thead><tbody><tr><td><code>window.onerror</code></td><td>未捕获的同步运行时错误</td></tr><tr><td><code>unhandledrejection</code></td><td>未处理的 Promise 拒绝</td></tr><tr><td><code>ErrorBoundary</code></td><td>React 组件渲染异常（含 <code>componentStack</code>）</td></tr></tbody></table><h3 id="请求体" tabindex="-1">请求体 <a class="header-anchor" href="#请求体" aria-label="Permalink to &quot;请求体&quot;">​</a></h3><table tabindex="0"><thead><tr><th>字段</th><th>类型</th><th>必填</th><th>说明</th></tr></thead><tbody><tr><td><code>type</code></td><td>string</td><td>否</td><td>错误类型，默认 <code>error</code></td></tr><tr><td><code>message</code></td><td>string</td><td>否</td><td>错误消息</td></tr><tr><td><code>stack</code></td><td>string</td><td>否</td><td>调用栈，服务端截断至 4000 字符</td></tr><tr><td><code>componentStack</code></td><td>string</td><td>否</td><td>React 组件栈</td></tr><tr><td><code>url</code></td><td>string</td><td>否</td><td>发生错误的页面地址</td></tr><tr><td><code>userAgent</code></td><td>string</td><td>否</td><td>客户端 UA，缺省取请求头</td></tr></tbody></table><h3 id="服务端行为" tabindex="-1">服务端行为 <a class="header-anchor" href="#服务端行为" aria-label="Permalink to &quot;服务端行为&quot;">​</a></h3><ol><li>按 IP 做<strong>进程内滑动窗口限流</strong>：60 秒内最多 30 次</li><li>超限返回 <code>429</code>，并在响应头 <code>Retry-After</code> 中给出重试秒数</li><li>通过 Winston 写入 <code>app/</code> 与 <code>error/</code> 日志目录，模块标记为 <code>Frontend</code></li></ol><h3 id="响应示例" tabindex="-1">响应示例 <a class="header-anchor" href="#响应示例" aria-label="Permalink to &quot;响应示例&quot;">​</a></h3><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{ </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;success&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;message&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;已记录&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> }</span></span></code></pre></div><h3 id="限流响应" tabindex="-1">限流响应 <a class="header-anchor" href="#限流响应" aria-label="Permalink to &quot;限流响应&quot;">​</a></h3><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{ </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;success&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">false</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;message&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;日志上报过于频繁，请稍后再试&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> }</span></span></code></pre></div><blockquote><p><strong>部署提示</strong>：限流基于 <code>req.ip</code>，Nginx 必须使用覆盖写方式传递真实客户端 IP：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>proxy_set_header X-Forwarded-For $remote_addr;</span></span></code></pre></div><p>并使用追加式传递，否则所有用户会共用网关 IP 的同一个桶，导致误封。</p></blockquote><hr><h2 id="危险操作审计" tabindex="-1">危险操作审计 <a class="header-anchor" href="#危险操作审计" aria-label="Permalink to &quot;危险操作审计&quot;">​</a></h2><h3 id="接口前缀" tabindex="-1">接口前缀 <a class="header-anchor" href="#接口前缀" aria-label="Permalink to &quot;接口前缀&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/api/dangerous-operations</span></span></code></pre></div><p>路由级统一挂载 <code>authMiddleware</code>，以下所有端点均需登录。</p><h3 id="危险操作类型" tabindex="-1">危险操作类型 <a class="header-anchor" href="#危险操作类型" aria-label="Permalink to &quot;危险操作类型&quot;">​</a></h3><table tabindex="0"><thead><tr><th>类型</th><th>说明</th></tr></thead><tbody><tr><td><code>DELETE_SINGLE</code></td><td>单条删除</td></tr><tr><td><code>DELETE_BATCH</code></td><td>批量删除</td></tr><tr><td><code>DELETE_ALL</code></td><td>全量删除</td></tr><tr><td><code>UPDATE_BATCH</code></td><td>批量更新</td></tr><tr><td><code>RESTORE</code></td><td>数据恢复</td></tr><tr><td><code>BATCH_RESTORE</code></td><td>批量恢复</td></tr><tr><td><code>PURGE</code></td><td>清理/彻底删除</td></tr></tbody></table><h3 id="风险等级判定" tabindex="-1">风险等级判定 <a class="header-anchor" href="#风险等级判定" aria-label="Permalink to &quot;风险等级判定&quot;">​</a></h3><table tabindex="0"><thead><tr><th>风险等级</th><th>判定条件</th></tr></thead><tbody><tr><td><code>EXTREME</code></td><td><code>DELETE_ALL</code>，或系统级操作，或批量删除超过 10 条</td></tr><tr><td><code>HIGH</code></td><td><code>DELETE_BATCH</code> 且数量在 4~10 条</td></tr><tr><td><code>MEDIUM</code></td><td><code>DELETE_BATCH</code> 且数量不超过 3 条；或目标存在关联数据</td></tr><tr><td><code>LOW</code></td><td>其他情况</td></tr></tbody></table><h3 id="记录危险操作" tabindex="-1">记录危险操作 <a class="header-anchor" href="#记录危险操作" aria-label="Permalink to &quot;记录危险操作&quot;">​</a></h3><div class="language-http vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">http</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">POST</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> /api/dangerous-operations/log</span></span></code></pre></div><h4 id="请求体-1" tabindex="-1">请求体 <a class="header-anchor" href="#请求体-1" aria-label="Permalink to &quot;请求体&quot;">​</a></h4><table tabindex="0"><thead><tr><th>字段</th><th>类型</th><th>必填</th><th>说明</th></tr></thead><tbody><tr><td><code>operationType</code></td><td>string</td><td>是</td><td>操作类型，取值见上表</td></tr><tr><td><code>operationName</code></td><td>string</td><td>否</td><td>操作名称（面向人阅读）</td></tr><tr><td><code>targetType</code></td><td>string</td><td>否</td><td>目标对象类型</td></tr><tr><td><code>targetId</code></td><td>string</td><td>否</td><td>目标对象 ID</td></tr><tr><td><code>targetName</code></td><td>string</td><td>否</td><td>目标对象名称</td></tr><tr><td><code>beforeState</code></td><td>object</td><td>否</td><td>操作前完整快照</td></tr><tr><td><code>metadata</code></td><td>object</td><td>否</td><td>附加信息，如 <code>{ itemCount, hasRelatedData }</code></td></tr><tr><td><code>success</code></td><td>boolean</td><td>否</td><td>是否成功，默认 <code>true</code></td></tr><tr><td><code>errorMessage</code></td><td>string</td><td>否</td><td>失败原因</td></tr></tbody></table><h3 id="查询危险操作日志" tabindex="-1">查询危险操作日志 <a class="header-anchor" href="#查询危险操作日志" aria-label="Permalink to &quot;查询危险操作日志&quot;">​</a></h3><div class="language-http vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">http</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">GET</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> /api/dangerous-operations/logs</span></span></code></pre></div><p>支持按操作类型、风险等级、时间范围、操作人筛选。</p><h3 id="清理历史日志" tabindex="-1">清理历史日志 <a class="header-anchor" href="#清理历史日志" aria-label="Permalink to &quot;清理历史日志&quot;">​</a></h3><div class="language-http vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">http</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">DELETE</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> /api/dangerous-operations/logs/clean</span></span></code></pre></div><p>用于按保留期清理，操作本身亦会被记录。</p><h3 id="风险评估" tabindex="-1">风险评估 <a class="header-anchor" href="#风险评估" aria-label="Permalink to &quot;风险评估&quot;">​</a></h3><div class="language-http vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">http</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">GET</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> /api/dangerous-operations/risk-assessment</span></span></code></pre></div><p>返回指定操作在当前数据规模下的风险预估，供前端在执行前弹出对应级别的二次确认。</p><blockquote><p><strong>前端配合</strong>：<code>frontend/src/config/dangerousOperationConfig.js</code> 定义了各类危险操作的确认文案与交互规格，<code>DangerConfirmModal</code> 组件按风险等级渲染不同强度的确认流程。</p></blockquote><hr><h2 id="公开设备信息牌" tabindex="-1">公开设备信息牌 <a class="header-anchor" href="#公开设备信息牌" aria-label="Permalink to &quot;公开设备信息牌&quot;">​</a></h2><h3 id="接口说明-1" tabindex="-1">接口说明 <a class="header-anchor" href="#接口说明-1" aria-label="Permalink to &quot;接口说明&quot;">​</a></h3><div class="language-http vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">http</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">GET</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> /p/devices/{deviceId}</span></span></code></pre></div><p><strong>完全免鉴权</strong>，用于生成可对外展示的设备信息 HTML 卡片（贴合在设备上的二维码扫码查看）。</p><p>这是<strong>唯一不位于 <code>/api</code> 前缀下</strong>的业务接口。</p><h3 id="设计约束-安全" tabindex="-1">设计约束（安全） <a class="header-anchor" href="#设计约束-安全" aria-label="Permalink to &quot;设计约束（安全）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>约束</th><th>说明</th></tr></thead><tbody><tr><td>字段白名单</td><td>仅允许展示固定字段，<strong>不含 <code>ipAddress</code> 与 <code>description</code></strong></td></tr><tr><td>禁止任意字段</td><td>旧版本支持 <code>?fields=ipAddress,description</code> 让免鉴权页面渲染敏感信息，现已修复为白名单校验</td></tr><tr><td>输出转义</td><td>所有字段经 HTML 转义后渲染，防止 XSS</td></tr></tbody></table><h3 id="可展示字段白名单" tabindex="-1">可展示字段白名单 <a class="header-anchor" href="#可展示字段白名单" aria-label="Permalink to &quot;可展示字段白名单&quot;">​</a></h3><table tabindex="0"><thead><tr><th>字段</th><th>中文标签</th></tr></thead><tbody><tr><td><code>deviceId</code></td><td>设备编号</td></tr><tr><td><code>name</code></td><td>名称</td></tr><tr><td><code>type</code></td><td>类型</td></tr><tr><td><code>model</code></td><td>型号</td></tr><tr><td><code>serialNumber</code></td><td>序列号</td></tr><tr><td><code>position</code></td><td>所在位置</td></tr><tr><td><code>status</code></td><td>状态</td></tr></tbody></table><h3 id="查询参数" tabindex="-1">查询参数 <a class="header-anchor" href="#查询参数" aria-label="Permalink to &quot;查询参数&quot;">​</a></h3><table tabindex="0"><thead><tr><th>参数</th><th>类型</th><th>必填</th><th>说明</th></tr></thead><tbody><tr><td><code>fields</code></td><td>string</td><td>否</td><td>逗号分隔的字段名，<strong>超出白名单的字段会被忽略</strong></td></tr></tbody></table><h3 id="响应" tabindex="-1">响应 <a class="header-anchor" href="#响应" aria-label="Permalink to &quot;响应&quot;">​</a></h3><p>返回 <code>text/html</code> 格式的信息卡片，包含设备基础信息与「本卡片由 IDC 资产系统生成」页脚。</p><h3 id="错误响应" tabindex="-1">错误响应 <a class="header-anchor" href="#错误响应" aria-label="Permalink to &quot;错误响应&quot;">​</a></h3><table tabindex="0"><thead><tr><th>HTTP</th><th>场景</th><th>页面内容</th></tr></thead><tbody><tr><td><code>404</code></td><td>设备不存在</td><td>设备不存在 / 未找到该设备，请核对设备编号或联系管理员。</td></tr><tr><td><code>500</code></td><td>生成失败</td><td>服务异常 / 信息牌生成失败，请稍后重试。</td></tr></tbody></table><h3 id="二维码生成" tabindex="-1">二维码生成 <a class="header-anchor" href="#二维码生成" aria-label="Permalink to &quot;二维码生成&quot;">​</a></h3><p>设备二维码在前端生成，包含以下两类能力：</p><table tabindex="0"><thead><tr><th>功能</th><th>说明</th></tr></thead><tbody><tr><td>单个二维码</td><td>设备管理列表与详情抽屉中的「二维码」操作，可预览与下载</td></tr><tr><td>批量二维码</td><td><code>DeviceQrBatchModal</code> 支持批量选择设备生成并打印信息牌</td></tr></tbody></table><blockquote><p>二维码内容为上述 <code>/p/devices/{deviceId}</code> 绝对地址，因此部署时前端与服务端的对外域名必须正确配置，否则扫码后无法访问。</p></blockquote>',62)])])}const k=d(i,[["render",o]]);export{b as __pageData,k as default};
